const methods: Record<string,Record<Language,string[]>> = {"greens": {"ja": ["野菜を洗い、食べやすく切る。", "沸騰した湯で2〜3分ゆで、冷まして水気を絞る。", "残りの材料と和え、味を見て器に盛る。"], "en": ["Wash and cut the vegetables.", "Boil for 2–3 minutes, cool and drain well.", "Mix with the remaining ingredients, taste and serve."], "zh-CN": ["洗净蔬菜并切成适口大小。", "沸水煮2至3分钟，放凉并沥干。", "加入其余材料拌匀，尝味后装盘。"], "zh-TW": ["洗淨蔬菜並切成適口大小。", "沸水煮2至3分鐘，放涼並瀝乾。", "加入其餘材料拌勻，嘗味後裝盤。"], "ko": ["채소를 씻어 먹기 좋게 자릅니다.", "끓는 물에 2~3분 데친 뒤 식혀 물기를 뺍니다.", "나머지 재료와 버무리고 맛을 확인해 담습니다."], "es": ["Lava y corta las verduras.", "Hierve 2–3 minutos, enfría y escurre.", "Mezcla con los demás ingredientes, prueba y sirve."], "fr": ["Lavez et coupez les légumes.", "Faites bouillir 2 à 3 minutes, refroidissez et égouttez.", "Mélangez aux autres ingrédients, goûtez et servez."]}, "miso": {"ja": ["野菜や豆腐を食べやすく切る。乾燥わかめは表示どおり戻す。", "だしを温め、肉や根菜があれば先に入れ、10〜15分ほど十分に火を通す。葉物・豆腐は仕上げに加える。", "火を弱めて味噌を溶く。沸騰させず温め、器に盛る。"], "en": ["Cut vegetables and tofu; rehydrate wakame as directed.", "Heat stock. Cook any meat and root vegetables thoroughly for 10–15 minutes; add greens and tofu near the end.", "Lower heat, dissolve miso and warm without boiling. Serve."], "zh-CN": ["蔬菜豆腐切块；干裙带菜按包装泡发。", "加热高汤，肉和根菜先煮10至15分钟至熟，再放叶菜和豆腐。", "转小火溶入味噌，温热但不要沸腾，盛碗。"], "zh-TW": ["蔬菜豆腐切塊；乾裙帶菜按包裝泡發。", "加熱高湯，肉和根菜先煮10至15分鐘至熟，再放葉菜和豆腐。", "轉小火溶入味噌，溫熱但不要沸騰，盛碗。"], "ko": ["채소와 두부를 자르고 마른 미역은 표시대로 불립니다.", "육수를 데워 고기와 뿌리채소를 먼저 10~15분 충분히 익힌 뒤 잎채소·두부를 넣습니다.", "불을 줄여 된장을 풀고 끓이지 않게 데워 담습니다."], "es": ["Corta verduras y tofu; hidrata el wakame según el envase.", "Calienta el caldo y cuece bien carne y raíces 10–15 minutos; añade hojas y tofu al final.", "Baja el fuego, disuelve el miso y calienta sin hervir."], "fr": ["Coupez légumes et tofu ; réhydratez le wakamé selon l’emballage.", "Chauffez le bouillon ; cuisez bien viande et racines 10 à 15 minutes, puis ajoutez feuilles et tofu.", "Baissez le feu, dissolvez le miso et chauffez sans bouillir."]}, "steam": {"ja": ["鶏肉を厚さ1cmほどにそぎ切りし、塩とレモン汁をなじませる。", "フライパンに鶏肉と水を入れ、ふたをして弱めの中火で8〜10分蒸す。", "中心温度75℃を1分以上保ったことを確認する。足りなければ追加加熱し、蒸し汁と盛る。"], "en": ["Slice chicken about 1 cm thick; season with salt and lemon.", "Put chicken and water in a pan, cover and steam gently for 8–10 minutes.", "Verify the center reaches 75°C for at least one minute; cook longer if needed and serve with juices."], "zh-CN": ["鸡肉切约1厘米厚，用盐和柠檬汁调味。", "鸡肉和水放入锅中，加盖中小火蒸8至10分钟。", "确认中心75℃持续至少1分钟，未达到则继续加热，配汤汁盛盘。"], "zh-TW": ["雞肉切約1公分厚，用鹽和檸檬汁調味。", "雞肉和水放入鍋中，加蓋中小火蒸8至10分鐘。", "確認中心75℃持續至少1分鐘，未達到則繼續加熱，配湯汁盛盤。"], "ko": ["닭을 약 1cm 두께로 썰어 소금과 레몬즙으로 간합니다.", "물과 함께 팬에 넣고 뚜껑을 덮어 중약불에 8~10분 찝니다.", "중심 75℃가 1분 이상 유지되는지 확인하고 부족하면 더 익혀 육즙과 담습니다."], "es": ["Corta el pollo de 1 cm; sazona con sal y limón.", "Ponlo con agua en una sartén, tapa y cocina al vapor 8–10 minutos.", "Comprueba 75°C en el centro durante al menos un minuto; prolonga si hace falta y sirve con su jugo."], "fr": ["Tranchez le poulet sur 1 cm ; assaisonnez de sel et citron.", "Mettez-le avec l’eau dans une poêle, couvrez et cuisez doucement 8 à 10 minutes.", "Vérifiez 75°C à cœur pendant au moins une minute ; prolongez si nécessaire et servez avec le jus."]}, "pickle": {"ja": ["きゅうりを薄切りにし、塩をまぶす。", "10分置き、水気を軽く絞って米酢と和える。", "冷蔵庫で15分冷やす。清潔な器に盛り、当日中に食べる。"], "en": ["Thinly slice cucumber and sprinkle with salt.", "Rest 10 minutes, squeeze gently and mix with rice vinegar.", "Chill 15 minutes, serve in a clean dish and eat the same day."], "zh-CN": ["黄瓜切薄片，撒盐。", "静置10分钟，轻轻挤水，拌入米醋。", "冷藏15分钟，用干净餐具盛装，当天食用。"], "zh-TW": ["小黃瓜切薄片，撒鹽。", "靜置10分鐘，輕輕擠水，拌入米醋。", "冷藏15分鐘，用乾淨餐具盛裝，當天食用。"], "ko": ["오이를 얇게 썰어 소금을 뿌립니다.", "10분 두고 살짝 물기를 짠 뒤 쌀식초와 섞습니다.", "15분 냉장하고 깨끗한 그릇에 담아 당일 먹습니다."], "es": ["Corta el pepino fino y añade sal.", "Reposa 10 minutos, escurre suavemente y añade vinagre.", "Enfría 15 minutos; sirve en un plato limpio y consume hoy."], "fr": ["Émincez le concombre et salez.", "Laissez 10 minutes, pressez doucement et ajoutez le vinaigre.", "Réfrigérez 15 minutes ; servez proprement et consommez le jour même."]}, "stir": {"ja": ["野菜を薄切りにする。卵があれば別の器で溶く。ゴーヤは種を除き、豆腐は水切りする。", "油を温め、野菜を中火で3〜5分炒める。卵や豆腐があれば加え、卵が固まるまで火を通す。", "しょうゆまたは塩で味を整え、1分炒め合わせる。ごまがあれば最後に加える。"], "en": ["Slice vegetables thinly; beat any eggs separately. Remove bitter-melon seeds and drain tofu if used.", "Heat oil and stir-fry vegetables 3–5 minutes. Add any eggs or tofu; cook eggs until set.", "Season with soy sauce or salt and stir one minute; add sesame at the end if used."], "zh-CN": ["蔬菜切薄片，鸡蛋另碗打散；苦瓜去籽，豆腐沥水。", "热油中火炒蔬菜3至5分钟，再加蛋或豆腐，蛋要炒至凝固。", "用酱油或盐调味，再炒1分钟；有芝麻则最后加入。"], "zh-TW": ["蔬菜切薄片，雞蛋另碗打散；苦瓜去籽，豆腐瀝水。", "熱油中火炒蔬菜3至5分鐘，再加蛋或豆腐，蛋要炒至凝固。", "用醬油或鹽調味，再炒1分鐘；有芝麻則最後加入。"], "ko": ["채소를 얇게 썰고 달걀은 따로 풉니다. 여주는 씨를 빼고 두부는 물기를 뺍니다.", "기름에 채소를 중불로 3~5분 볶고 달걀·두부를 넣어 달걀이 굳을 때까지 익힙니다.", "간장 또는 소금으로 간하고 1분 더 볶습니다. 깨는 마지막에 넣습니다."], "es": ["Corta las verduras finas y bate los huevos si se usan; quita semillas del melón y escurre el tofu.", "Saltea las verduras en aceite 3–5 minutos; añade huevo o tofu y cuaja bien el huevo.", "Sazona con soja o sal y saltea un minuto más; añade sésamo al final."], "fr": ["Émincez les légumes ; battez les œufs, épépinez la margose et égouttez le tofu si utilisés.", "Faites sauter les légumes dans l’huile 3 à 5 minutes ; ajoutez œufs ou tofu et cuisez les œufs complètement.", "Assaisonnez de soja ou sel et remuez une minute ; ajoutez le sésame à la fin."]}, "stuff": {"ja": ["パプリカを半分にして種を除く。みじん切り玉ねぎを肉に混ぜて詰める。", "肉側を下にして中火で2分焼き、水を加えてふたをし10〜12分蒸し焼きにする。", "肉の中心75℃を1分以上確認し、足りなければ追加加熱する。"], "en": ["Halve and deseed peppers. Mix chopped onion into meat and fill.", "Sear meat-side down 2 minutes, add water, cover and cook 10–12 minutes.", "Check meat reaches 75°C for one minute; continue cooking if needed."], "zh-CN": ["彩椒对半去籽，肉末拌碎洋葱后填入。", "肉面朝下煎2分钟，加水加盖煮10至12分钟。", "确认肉中心75℃至少1分钟，未达到则继续加热。"], "zh-TW": ["彩椒對半去籽，絞肉拌碎洋蔥後填入。", "肉面朝下煎2分鐘，加水加蓋煮10至12分鐘。", "確認肉中心75℃至少1分鐘，未達到則繼續加熱。"], "ko": ["파프리카를 반으로 잘라 씨를 빼고 다진 양파와 고기를 섞어 채웁니다.", "고기 면을 아래로 2분 굽고 물을 넣어 덮어 10~12분 익힙니다.", "고기 중심75℃ 1분 이상을 확인하고 필요하면 더 익힙니다."], "es": ["Parte y despepita los pimientos; rellena con carne y cebolla picada.", "Dora la cara de carne 2 minutos; añade agua, tapa y cocina 10–12 minutos.", "Verifica 75°C en el centro un minuto; prolonga si hace falta."], "fr": ["Coupez et épépinez les poivrons ; farcissez avec viande et oignon haché.", "Saisissez côté viande 2 minutes, ajoutez eau, couvrez et cuisez 10 à 12 minutes.", "Vérifiez 75°C à cœur une minute ; prolongez si nécessaire."]}, "yogurt": {"ja": ["いちごを流水で洗い、へたを取る。", "水気を拭き、半分に切る。", "ヨーグルトを器に分け、いちごをのせて冷たいうちに食べる。"], "en": ["Wash strawberries and remove stalks.", "Pat dry and halve.", "Divide yogurt into bowls, top with fruit and eat chilled."], "zh-CN": ["草莓洗净去蒂。", "擦干并切半。", "酸奶分碗，放上草莓，趁冷食用。"], "zh-TW": ["草莓洗淨去蒂。", "擦乾並切半。", "優格分碗，放上草莓，趁冷食用。"], "ko": ["딸기를 씻어 꼭지를 뗍니다.", "물기를 닦고 반으로 자릅니다.", "요거트를 나눠 담고 딸기를 올려 차게 먹습니다."], "es": ["Lava las fresas y quita los tallos.", "Seca y corta por la mitad.", "Reparte el yogur, añade fresas y sirve frío."], "fr": ["Lavez et équeutez les fraises.", "Séchez et coupez en deux.", "Répartissez le yaourt, ajoutez les fraises et servez frais."]}, "simmer": {"ja": ["野菜をひと口大に切る。肉があれば鍋で軽く炒める。", "野菜、だしまたは水、しょうゆ、砂糖を加え、落としぶたで15〜25分煮る。", "野菜が柔らかく肉が十分に加熱されたことを確認し、火を止め5分味をなじませる。"], "en": ["Cut vegetables into bite-size pieces; briefly sauté meat if used.", "Add vegetables, stock or water, soy and sugar. Cover loosely and simmer 15–25 minutes.", "Check vegetables are tender and meat fully cooked; rest off heat five minutes."], "zh-CN": ["蔬菜切块，有肉则先略炒。", "加蔬菜、高汤或水、酱油和糖，加盖小火煮15至25分钟。", "确认蔬菜柔软、肉全熟，关火静置5分钟。"], "zh-TW": ["蔬菜切塊，有肉則先略炒。", "加蔬菜、高湯或水、醬油和糖，加蓋小火煮15至25分鐘。", "確認蔬菜柔軟、肉全熟，關火靜置5分鐘。"], "ko": ["채소를 자르고 고기가 있으면 먼저 살짝 볶습니다.", "채소·육수나 물·간장·설탕을 넣어 덮고 15~25분 끓입니다.", "채소가 부드럽고 고기가 완전히 익으면 불을 끄고 5분 둡니다."], "es": ["Corta las verduras; saltea la carne si se usa.", "Añade verduras, caldo o agua, soja y azúcar; tapa ligeramente y cuece 15–25 minutos.", "Comprueba que todo esté bien cocido y reposa cinco minutos."], "fr": ["Coupez les légumes et saisissez la viande si utilisée.", "Ajoutez légumes, bouillon ou eau, soja et sucre ; couvrez et mijotez 15 à 25 minutes.", "Vérifiez la cuisson complète, puis reposez cinq minutes."]}, "rice": {"ja": ["米を洗い、分量の水で30分浸す。", "さつまいもを1cm角に切り、水に5分さらして水切りし、米に塩とともにのせる。", "炊飯器の通常モードで炊き、10分蒸らしてやさしく混ぜる。"], "en": ["Rinse rice and soak in measured water 30 minutes.", "Dice sweet potato to 1 cm, soak five minutes and drain; place on rice with salt.", "Use the rice cooker’s normal cycle, rest 10 minutes and fold gently."], "zh-CN": ["米洗净，按配方水量泡30分钟。", "红薯切1厘米块，泡水5分钟沥干，加盐放在米上。", "电饭煲普通模式煮熟，焖10分钟后轻拌。"], "zh-TW": ["米洗淨，按配方水量泡30分鐘。", "地瓜切1公分塊，泡水5分鐘瀝乾，加鹽放在米上。", "電鍋普通模式煮熟，燜10分鐘後輕拌。"], "ko": ["쌀을 씻어 정량 물에30분 불립니다.", "고구마를1cm로 잘라5분 물에 담갔다 건져 소금과 쌀 위에 얹습니다.", "밥솥 일반 모드로 취사 후10분 뜸 들여 섞습니다."], "es": ["Lava el arroz y remoja en el agua medida 30 minutos.", "Corta boniato de 1 cm, remoja cinco minutos y escurre; añade con sal sobre el arroz.", "Usa el ciclo normal de la arrocera, reposa 10 minutos y mezcla."], "fr": ["Rincez le riz, trempez-le 30 minutes dans l’eau mesurée.", "Coupez la patate douce en dés de 1 cm, trempez cinq minutes, égouttez et posez sur le riz avec le sel.", "Cuisez au cycle normal du cuiseur, reposez 10 minutes et mélangez."]}, "fry": {"ja": ["とうもろこしに小麦粉と水を混ぜ、小さなまとまりにする。", "深い鍋で油を170℃にし、少量ずつ3〜4分揚げる。水滴を油に入れない。", "両面が固まりきつね色になったら油を切り、塩を添える。熱い油の取り扱いに注意する。"], "en": ["Mix corn, flour and water into small clusters.", "Heat oil in a deep pan to 170°C; fry small batches 3–4 minutes. Keep water away from hot oil.", "Drain when set and golden; serve with salt. Handle hot oil carefully."], "zh-CN": ["玉米加面粉和水拌成小团。", "深锅油温170℃，分批炸3至4分钟；不要让水滴入热油。", "两面凝固定型呈金黄后沥油，撒盐；注意热油安全。"], "zh-TW": ["玉米加麵粉和水拌成小團。", "深鍋油溫170℃，分批炸3至4分鐘；不要讓水滴入熱油。", "兩面凝固定型呈金黃後瀝油，撒鹽；注意熱油安全。"], "ko": ["옥수수·밀가루·물을 섞어 작게 뭉칩니다.", "깊은 냄비에서170℃ 기름에 조금씩3~4분 튀깁니다. 물이 뜨거운 기름에 닿지 않게 합니다.", "양면이 굳고 노릇해지면 기름을 빼고 소금을 곁들입니다. 화상에 주의하세요."], "es": ["Mezcla maíz, harina y agua en porciones pequeñas.", "Fríe por tandas 3–4 minutos en aceite a 170°C; evita gotas de agua.", "Escurre cuando estén firmes y doradas; sirve con sal y cuida el aceite caliente."], "fr": ["Mélangez maïs, farine et eau en petites portions.", "Frisez par lots 3 à 4 minutes dans l’huile à 170°C ; évitez les gouttes d’eau.", "Égouttez une fois fermes et dorées, servez avec du sel ; attention à l’huile chaude."]}, "fishsimmer": {"ja": ["大根を2cm厚に切り、10分下ゆでする。ぶりは熱湯をかけて洗う。", "水、しょうゆ、砂糖、薄切りしょうがと大根を鍋で煮立て、魚を加える。", "落としぶたをして15〜20分煮る。魚の中心まで十分火を通し、骨に注意して盛る。"], "en": ["Cut radish 2 cm thick and parboil 10 minutes; blanch and rinse fish.", "Bring water, soy, sugar, sliced ginger and radish to a simmer; add fish.", "Cover loosely and simmer 15–20 minutes until fish is fully cooked; watch for bones."], "zh-CN": ["萝卜切2厘米厚，先煮10分钟；鱼用热水烫洗。", "水、酱油、糖、姜片和萝卜煮开，加入鱼。", "加盖煮15至20分钟，确认鱼全熟，注意鱼刺。"], "zh-TW": ["蘿蔔切2公分厚，先煮10分鐘；魚用熱水燙洗。", "水、醬油、糖、薑片和蘿蔔煮開，加入魚。", "加蓋煮15至20分鐘，確認魚全熟，注意魚刺。"], "ko": ["무를2cm로 잘라10분 삶고 생선은 뜨거운 물에 데쳐 씻습니다.", "물·간장·설탕·생강·무를 끓여 생선을 넣습니다.", "덮어15~20분 끓여 완전히 익히고 가시에 주의합니다."], "es": ["Corta daikon de 2 cm y hierve 10 minutos; escalda y lava el pescado.", "Hierve agua, soja, azúcar, jengibre y daikon; añade pescado.", "Cuece tapado 15–20 minutos hasta cocción completa; cuidado con espinas."], "fr": ["Coupez le daikon sur 2 cm, précuisez 10 minutes ; blanchissez et rincez le poisson.", "Portez eau, soja, sucre, gingembre et daikon à frémissement ; ajoutez le poisson.", "Mijotez couvert 15 à 20 minutes jusqu’à cuisson complète ; attention aux arêtes."]}, "grill": {"ja": ["魚の水気を拭き、塩を振って10分置く。", "フライパンに油を薄くひき、皮側から中火で4〜5分焼く。", "返してさらに4〜5分、中心まで火を通す。時間は厚さに合わせて延ばし、骨に注意して食べる。"], "en": ["Pat fish dry, salt and rest 10 minutes.", "Lightly oil a pan; cook skin-side down 4–5 minutes over medium heat.", "Turn and cook another 4–5 minutes until fully done; adjust for thickness and watch for bones."], "zh-CN": ["擦干鱼，撒盐静置10分钟。", "平底锅薄抹油，鱼皮面中火煎4至5分钟。", "翻面再煎4至5分钟至中心熟透，按厚度延长；注意鱼刺。"], "zh-TW": ["擦乾魚，撒鹽靜置10分鐘。", "平底鍋薄抹油，魚皮面中火煎4至5分鐘。", "翻面再煎4至5分鐘至中心熟透，按厚度延長；注意魚刺。"], "ko": ["생선 물기를 닦고 소금을 뿌려10분 둡니다.", "팬에 기름을 얇게 바르고 껍질 면부터 중불4~5분 굽습니다.", "뒤집어4~5분 더 완전히 익힙니다. 두께에 따라 늘리고 가시에 주의합니다."], "es": ["Seca el pescado, sala y deja 10 minutos.", "Engrasa la sartén y cocina por la piel 4–5 minutos.", "Gira y cocina 4–5 minutos más; ajusta al grosor y cuida las espinas."], "fr": ["Séchez le poisson, salez et reposez 10 minutes.", "Huilez légèrement la poêle ; cuisez côté peau 4 à 5 minutes.", "Retournez et cuisez 4 à 5 minutes de plus ; adaptez à l’épaisseur et surveillez les arêtes."]}, "soup": {"ja": ["白菜をざく切り、豆腐をひと口大にする。", "だしを煮立て、白菜を5〜8分煮る。", "豆腐を加えて3分温め、塩で調味する。豆腐が崩れないよう盛る。"], "en": ["Chop cabbage and cube tofu.", "Bring stock to a simmer and cook cabbage 5–8 minutes.", "Add tofu, warm three minutes and season with salt; serve gently."], "zh-CN": ["白菜切块，豆腐切适口大小。", "高汤煮开，放白菜煮5至8分钟。", "加豆腐温热3分钟，用盐调味，轻轻盛碗。"], "zh-TW": ["白菜切塊，豆腐切適口大小。", "高湯煮開，放白菜煮5至8分鐘。", "加豆腐溫熱3分鐘，用鹽調味，輕輕盛碗。"], "ko": ["배추와 두부를 자릅니다.", "육수를 끓여 배추를5~8분 익힙니다.", "두부를 넣어3분 데워 소금으로 간하고 조심히 담습니다."], "es": ["Corta col y tofu.", "Hierve el caldo y cuece la col 5–8 minutos.", "Añade tofu, calienta tres minutos y sala; sirve con cuidado."], "fr": ["Coupez chou et tofu.", "Frémissez le bouillon et cuisez le chou 5 à 8 minutes.", "Ajoutez le tofu, chauffez trois minutes et salez ; servez délicatement."]}, "foil": {"ja": ["玉ねぎを薄切りにし、きのこをほぐす。", "アルミホイルに野菜・鮭・バターをのせて包み、フライパンに置く。", "包みの外に水を注ぎ、ふたをして中火で12〜15分蒸す。魚が中心まで加熱されるまで延ばし、蒸気に注意して開く。"], "en": ["Slice onion and separate mushrooms.", "Place vegetables, salmon and butter on foil; seal and put in a pan.", "Add water outside parcels, cover and steam 12–15 minutes; extend until fish is fully cooked. Open carefully: hot steam."], "zh-CN": ["洋葱切片，蘑菇分小朵。", "铝箔放蔬菜、鱼和黄油，封好放入锅。", "包外加水，加盖中火蒸12至15分钟至鱼全熟；小心蒸汽打开。"], "zh-TW": ["洋蔥切片，菇分小朵。", "鋁箔放蔬菜、魚和奶油，封好放入鍋。", "包外加水，加蓋中火蒸12至15分鐘至魚全熟；小心蒸汽打開。"], "ko": ["양파를 썰고 버섯을 나눕니다.", "포일에 채소·연어·버터를 담아 밀봉해 팬에 놓습니다.", "포일 밖에 물을 붓고 덮어12~15분 생선이 완전히 익도록 찝니다. 증기에 주의해 엽니다."], "es": ["Corta cebolla y separa setas.", "Envuelve verduras, salmón y mantequilla en aluminio; pon en sartén.", "Añade agua fuera, tapa y cocina 12–15 minutos hasta cocción completa; abre con cuidado del vapor."], "fr": ["Émincez l’oignon et séparez les champignons.", "Enveloppez légumes, saumon et beurre dans l’aluminium ; posez dans la poêle.", "Versez l’eau à l’extérieur, couvrez et cuisez 12 à 15 minutes jusqu’à cuisson complète ; attention à la vapeur."]}, "hijiki": {"ja": ["ひじきを包装の表示どおり戻し、水を捨て流水でよく洗う。", "にんじんを細切りにし、ひじき・ゆで黒豆・だしを鍋に入れる。", "しょうゆと砂糖を加え、10〜15分煮て水分を少し飛ばす。"], "en": ["Rehydrate hijiki as directed, discard soaking water and rinse thoroughly.", "Julienne carrot; put it with hijiki, cooked beans and stock in a pan.", "Add soy and sugar, simmer 10–15 minutes and reduce slightly."], "zh-CN": ["按包装泡发羊栖菜，倒掉泡水并充分冲洗。", "胡萝卜切丝，与羊栖菜、熟黑豆和高汤入锅。", "加酱油糖煮10至15分钟，略收汁。"], "zh-TW": ["按包裝泡發羊棲菜，倒掉泡水並充分沖洗。", "紅蘿蔔切絲，與羊棲菜、熟黑豆和高湯入鍋。", "加醬油糖煮10至15分鐘，略收汁。"], "ko": ["톳을 표시대로 불려 물을 버리고 충분히 씻습니다.", "당근을 채 썰어 톳·삶은 콩·육수와 냄비에 넣습니다.", "간장·설탕을 넣어10~15분 끓여 살짝 졸입니다."], "es": ["Hidrata hijiki según el envase; desecha el agua y enjuaga bien.", "Pon zanahoria en tiras, hijiki, judías cocidas y caldo en una olla.", "Añade soja y azúcar y cuece 10–15 minutos reduciendo un poco."], "fr": ["Réhydratez le hijiki selon l’emballage, jetez l’eau et rincez bien.", "Mettez carotte en julienne, hijiki, haricots cuits et bouillon dans une casserole.", "Ajoutez soja et sucre, mijotez 10 à 15 minutes et réduisez légèrement."]}, "nameko": {"ja": ["なめこをさっと洗い、沸騰した湯で2〜3分しっかりゆでて水切りする。", "大根を洗って皮をむき、すりおろして軽く水気を切る。", "冷ましたなめこと大根おろしを合わせ、ポン酢をかける。"], "en": ["Rinse nameko, boil thoroughly for 2–3 minutes and drain.", "Wash, peel and grate radish; drain lightly.", "Cool mushrooms, combine with radish and dress with ponzu."], "zh-CN": ["滑子菇洗净，沸水充分煮2至3分钟沥干。", "萝卜洗净去皮磨泥，轻轻沥水。", "蘑菇放凉拌萝卜泥，淋柑橘酱油。"], "zh-TW": ["滑子菇洗淨，沸水充分煮2至3分鐘瀝乾。", "蘿蔔洗淨去皮磨泥，輕輕瀝水。", "菇放涼拌蘿蔔泥，淋柑橘醬油。"], "ko": ["나메코를 씻어 끓는 물에2~3분 충분히 삶아 건집니다.", "무를 씻어 껍질을 벗기고 갈아 물기를 살짝 뺍니다.", "식힌 버섯과 무즙을 섞어 폰즈를 뿌립니다."], "es": ["Lava nameko, hierve bien 2–3 minutos y escurre.", "Lava, pela y ralla daikon; escurre un poco.", "Enfría las setas, mezcla con daikon y aliña con ponzu."], "fr": ["Rincez les nameko, cuisez à l’eau bouillante 2 à 3 minutes et égouttez.", "Lavez, pelez et râpez le daikon, égouttez légèrement.", "Refroidissez les champignons, mélangez au daikon et ajoutez le ponzu."]}, "clam": {"ja": ["しじみを包装の表示どおり砂抜きし、殻をこすり洗いする。", "水と貝を鍋に入れ加熱し、開いた後も十分煮る。開かない貝は取り除く。", "火を弱めて味噌を溶き、沸騰させず温めて盛る。"], "en": ["Purge clams as directed and scrub shells.", "Heat clams in water and cook thoroughly after they open; discard unopened shells.", "Lower heat, dissolve miso and warm without boiling."], "zh-CN": ["按包装让蚬贝吐沙，搓洗贝壳。", "贝和水入锅加热，开口后充分煮熟，丢弃不开口的贝。", "转小火溶入味噌，温热不煮沸后盛碗。"], "zh-TW": ["按包裝讓蜆吐沙，搓洗貝殼。", "貝和水入鍋加熱，開口後充分煮熟，丟棄不開口的貝。", "轉小火溶入味噌，溫熱不煮沸後盛碗。"], "ko": ["재첩을 표시대로 해감하고 껍데기를 문질러 씻습니다.", "물과 함께 끓여 입이 열린 뒤 충분히 익히며 안 열린 것은 버립니다.", "불을 줄여 된장을 풀고 끓이지 않게 데워 담습니다."], "es": ["Purga las almejas según el envase y frota las conchas.", "Calienta con agua y cuece bien tras abrirse; desecha las cerradas.", "Baja el fuego, disuelve miso y calienta sin hervir."], "fr": ["Dégorgez les palourdes selon l’emballage et frottez les coquilles.", "Chauffez dans l’eau et cuisez bien après ouverture ; jetez celles restées fermées.", "Baissez le feu, dissolvez le miso et chauffez sans bouillir."]}, "tomato-egg": {"ja": ["トマトを洗って薄切りにする。 卵は別の器で溶く。", "油を温め、中火で野菜を3〜5分炒める。 卵を加えて、完全に固まるまで炒める。", "塩で味を整え、1分炒め合わせて盛る。"], "en": ["Wash and thinly slice Tomato. Beat the eggs separately.", "Heat oil and stir-fry the vegetables over medium heat for 3–5 minutes. Add eggs and cook until fully set.", "Season with Salt, stir one minute and serve."], "zh-CN": ["洗净番茄并切薄片。 鸡蛋另碗打散。", "热油中火炒蔬菜3至5分钟。 加入鸡蛋炒至完全凝固。", "用盐调味，再炒1分钟装盘。"], "zh-TW": ["洗淨番茄並切薄片。 雞蛋另碗打散。", "熱油中火炒蔬菜3至5分鐘。 加入雞蛋炒至完全凝固。", "用鹽調味，再炒1分鐘裝盤。"], "ko": ["토마토를 씻어 얇게 자릅니다. 달걀은 따로 풉니다.", "기름을 데워 채소를 중불에3~5분 볶습니다. 달걀을 넣어 완전히 굳을 때까지 익힙니다.", "소금으로 간하고1분 더 볶아 담습니다."], "es": ["Lava y corta en láminas Tomate. Bate el huevo aparte.", "Calienta aceite y saltea las verduras 3–5 minutos a fuego medio. Añade el huevo y cocina hasta que cuaje por completo.", "Sazona con Sal, remueve un minuto y sirve."], "fr": ["Lavez et émincez Tomate. Battez les œufs séparément.", "Chauffez l’huile et faites sauter les légumes 3 à 5 minutes à feu moyen. Ajoutez les œufs et cuisez-les complètement.", "Assaisonnez avec Sel, remuez une minute et servez."]}, "champuru": {"ja": ["ゴーヤを洗って薄切りにする。 卵は別の器で溶く。 ゴーヤの種を除き、豆腐は水切りする。", "油を温め、中火で野菜を3〜5分炒める。 豆腐と卵を加えて、卵が完全に固まるまで炒める。", "しょうゆで味を整え、1分炒め合わせて盛る。"], "en": ["Wash and thinly slice Bitter melon. Beat the eggs separately. Remove bitter-melon seeds and drain the tofu.", "Heat oil and stir-fry the vegetables over medium heat for 3–5 minutes. Add tofu and eggs, cooking until the eggs are fully set.", "Season with Soy sauce, stir one minute and serve."], "zh-CN": ["洗净苦瓜并切薄片。 鸡蛋另碗打散。 苦瓜去籽，豆腐沥水。", "热油中火炒蔬菜3至5分钟。 加入豆腐和鸡蛋，炒至鸡蛋完全凝固。", "用酱油调味，再炒1分钟装盘。"], "zh-TW": ["洗淨苦瓜並切薄片。 雞蛋另碗打散。 苦瓜去籽，豆腐瀝水。", "熱油中火炒蔬菜3至5分鐘。 加入豆腐和雞蛋，炒至雞蛋完全凝固。", "用醬油調味，再炒1分鐘裝盤。"], "ko": ["여주를 씻어 얇게 자릅니다. 달걀은 따로 풉니다. 여주 씨를 빼고 두부 물기를 뺍니다.", "기름을 데워 채소를 중불에3~5분 볶습니다. 두부와 달걀을 넣어 달걀이 완전히 굳도록 익힙니다.", "간장으로 간하고1분 더 볶아 담습니다."], "es": ["Lava y corta en láminas Melón amargo. Bate el huevo aparte. Quita las semillas del melón y escurre el tofu.", "Calienta aceite y saltea las verduras 3–5 minutos a fuego medio. Añade tofu y huevo y cocina hasta que el huevo cuaje.", "Sazona con Salsa de soja, remueve un minuto y sirve."], "fr": ["Lavez et émincez Margose. Battez les œufs séparément. Épépinez la margose et égouttez le tofu.", "Chauffez l’huile et faites sauter les légumes 3 à 5 minutes à feu moyen. Ajoutez tofu et œufs et cuisez les œufs complètement.", "Assaisonnez avec Sauce soja, remuez une minute et servez."]}, "carrot-egg": {"ja": ["にんじんを洗って薄切りにする。 卵は別の器で溶く。", "油を温め、中火で野菜を3〜5分炒める。 卵を加えて、完全に固まるまで炒める。", "しょうゆで味を整え、1分炒め合わせて盛る。"], "en": ["Wash and thinly slice Carrot. Beat the eggs separately.", "Heat oil and stir-fry the vegetables over medium heat for 3–5 minutes. Add eggs and cook until fully set.", "Season with Soy sauce, stir one minute and serve."], "zh-CN": ["洗净胡萝卜并切薄片。 鸡蛋另碗打散。", "热油中火炒蔬菜3至5分钟。 加入鸡蛋炒至完全凝固。", "用酱油调味，再炒1分钟装盘。"], "zh-TW": ["洗淨紅蘿蔔並切薄片。 雞蛋另碗打散。", "熱油中火炒蔬菜3至5分鐘。 加入雞蛋炒至完全凝固。", "用醬油調味，再炒1分鐘裝盤。"], "ko": ["당근를 씻어 얇게 자릅니다. 달걀은 따로 풉니다.", "기름을 데워 채소를 중불에3~5분 볶습니다. 달걀을 넣어 완전히 굳을 때까지 익힙니다.", "간장으로 간하고1분 더 볶아 담습니다."], "es": ["Lava y corta en láminas Zanahoria. Bate el huevo aparte.", "Calienta aceite y saltea las verduras 3–5 minutos a fuego medio. Añade el huevo y cocina hasta que cuaje por completo.", "Sazona con Salsa de soja, remueve un minuto y sirve."], "fr": ["Lavez et émincez Carotte. Battez les œufs séparément.", "Chauffez l’huile et faites sauter les légumes 3 à 5 minutes à feu moyen. Ajoutez les œufs et cuisez-les complètement.", "Assaisonnez avec Sauce soja, remuez une minute et servez."]}, "lotus": {"ja": ["れんこんを洗って薄切りにする。", "油を温め、中火で野菜を3〜5分炒める。", "しょうゆで味を整え、1分炒め合わせて盛る。 砂糖を一緒に加え、最後にごまを振る。"], "en": ["Wash and thinly slice Lotus root.", "Heat oil and stir-fry the vegetables over medium heat for 3–5 minutes.", "Season with Soy sauce, stir one minute and serve. Add sugar with the sauce and finish with sesame."], "zh-CN": ["洗净莲藕并切薄片。", "热油中火炒蔬菜3至5分钟。", "用酱油调味，再炒1分钟装盘。 调味时加糖，最后撒芝麻。"], "zh-TW": ["洗淨蓮藕並切薄片。", "熱油中火炒蔬菜3至5分鐘。", "用醬油調味，再炒1分鐘裝盤。 調味時加糖，最後撒芝麻。"], "ko": ["연근를 씻어 얇게 자릅니다.", "기름을 데워 채소를 중불에3~5분 볶습니다.", "간장으로 간하고1분 더 볶아 담습니다. 간할 때 설탕을 넣고 마지막에 깨를 뿌립니다."], "es": ["Lava y corta en láminas Raíz de loto.", "Calienta aceite y saltea las verduras 3–5 minutos a fuego medio.", "Sazona con Salsa de soja, remueve un minuto y sirve. Añade azúcar al sazonar y termina con sésamo."], "fr": ["Lavez et émincez Racine de lotus.", "Chauffez l’huile et faites sauter les légumes 3 à 5 minutes à feu moyen.", "Assaisonnez avec Sauce soja, remuez une minute et servez. Ajoutez le sucre à l’assaisonnement et terminez avec le sésame."]}};
const luck: Record<Language,string> = {"ja": "器に余白を残して彩りを楽しみ、最初のひと口で今日大切にしたいことを一つ思い浮かべてみませんか。食卓を整える小さな習慣としての「開運ポイント」です。", "en": "Leave space on the plate to enjoy the colors, and name one thing you want to care for with the first bite. This is a symbolic ritual for an attentive meal.", "zh-CN": "留一点摆盘空间欣赏色彩，第一口时想想今天最珍惜的一件事。这是让用餐更用心的象征性仪式。", "zh-TW": "留一點擺盤空間欣賞色彩，第一口時想想今天最珍惜的一件事。這是讓用餐更用心的象徵性儀式。", "ko": "접시에 여백을 남겨 색을 즐기고 첫입에 오늘 소중히 여길 한 가지를 떠올려보세요. 식탁을 돌보는 상징적인 습관입니다.", "es": "Deja espacio en el plato para apreciar los colores y piensa en algo que quieras cuidar con el primer bocado. Es un pequeño ritual simbólico de atención.", "fr": "Laissez de l’espace dans l’assiette pour apprécier les couleurs et pensez à une chose à préserver dès la première bouchée. Un petit rituel symbolique d’attention."};
