const mealSteps: Record<Language,[string,string]> = {
  ja:['分量は2人前です。材料を量り、手と調理器具を清潔にします。生肉・魚用の器具は野菜用と分け、加熱前後で洗ってください。','2つの器へ等分し、主材料を中央に、彩りのある具を見えるよう盛ります。熱い料理は温かいうちに、冷たい料理は清潔な器で当日中に楽しみましょう。'],
  en:['Measure for two servings. Wash hands and utensils; separate raw meat/fish utensils and clean before and after cooking.','Divide between two plates, showing the main ingredients and colors. Serve hot dishes warm; keep cold dishes clean and eat the same day.'],
  'zh-CN':['按2人份称量。洗手并清洁器具，生肉鱼器具与蔬菜分开，烹饪前后清洗。','均分两份，主料放中间，展示配菜色彩。热菜趁热，冷菜用干净器皿并当天食用。'],
  'zh-TW':['按2人份秤量。洗手並清潔器具，生肉魚器具與蔬菜分開，烹飪前後清洗。','均分兩份，主料放中間，展示配菜色彩。熱菜趁熱，冷菜用乾淨器皿並當天食用。'],
  ko:['2인분을 계량하세요. 손과 도구를 씻고 생고기·생선 도구를 분리해 조리 전후 씻으세요.','두 접시에 나누고 주재료와 색감이 보이게 담으세요. 따뜻한 음식은 따뜻하게, 찬 음식은 청결히 당일 드세요.'],
  es:['Mide para dos raciones. Lava manos y utensilios; separa los de carne y pescado crudos y limpia antes y después.','Reparte entre dos platos mostrando ingredientes y colores. Sirve caliente lo cocinado; conserva limpio lo frío y consúmelo hoy.'],
  fr:['Mesurez pour deux portions. Lavez mains et ustensiles ; séparez ceux pour viande et poisson crus et nettoyez avant et après.','Répartissez dans deux assiettes en montrant ingrédients et couleurs. Servez chaud ; gardez les plats froids propres et consommez-les le jour même.'],
};
export function recipeDetails(recipe: Recipe, language: Language) { return {name:recipe.names[language], ingredients:recipe.ingredients.map(i => `${ingredients[i.id]?.[language] ?? i.id} · ${i.amount}`), steps:[...(methods[recipe.method]?.[language] ?? []), mealSteps[language][1]], luck:luck[language].replace('開運ポイント','運気アップポイント')}; }

