const ELEMENTS: Element[] = ['wood', 'fire', 'earth', 'metal', 'water'];
const dayIndex = (day: string) => { const t = Date.parse(`${day}T00:00:00Z`); return Number.isFinite(t) ? Math.floor(t / 86400000) : 0; };
/** Daily candidates for one course: in-season dishes (matching the biorhythm when known) on alternating days, evergreen plus in-season dishes otherwise. */
export function courseCandidates(course: Course, element: Element, day = '', birthDate?: string) {
  const all = luckyRecipes.filter(r => recipeCourse(r.id) === course);
  if (!day) return all;
  const season = seasonOf(day), rhythm = rhythmOf(birthDate, day);
  const seasonal = all.filter(r => r.season === season);
  const tuned = rhythm ? seasonal.filter(r => r.rhythm === rhythm) : seasonal;
  const useSeason = (dayIndex(day) + COURSE_ORDER.indexOf(course)) % 2 === 0;
  const inSeason = all.filter(r => !r.season || r.season === season);
  const pool = useSeason ? (tuned.length ? tuned : seasonal.length ? seasonal : inSeason) : inSeason;
  // Element dishes lead the list so the order stays personal while still rotating through every dish.
  return [...pool.filter(r => r.element === element), ...pool.filter(r => r.element !== element)];
}
/** Disjoint calendar-day lanes guarantee no adjacent-day repeats, even at season/year boundaries. */
export function recipeCuisine(recipe: Recipe): 'japanese' | 'western' | 'asian' | 'vegetable' | 'sweet' {
  if (isSweetDessert(recipe)) return 'sweet';
  if (['tomato-egg','eggplant-mapo','snappea-egg','pepper-carrot'].includes(recipe.id)) return 'asian';
  if (['lemon-chicken','stuffed-pepper','salmon-foil','mushroom-butter-saute','tomato-gazpacho','sweetpotato-potage','new-onion-soup'].includes(recipe.id)) return 'western';
  if (recipeCourse(recipe.id)==='side') return 'vegetable';
  return 'japanese';
}
export const recipesForElement = (element: Element, day = '', births?: string | string[]) => COURSE_ORDER.flatMap((course, i) => {
  const dates = (Array.isArray(births) ? births : births ? [births] : []).filter(Boolean).sort();
  if (!day) return courseCandidates(course, element).slice(0, 1);
  const ordinal = dayIndex(day);
  const all = luckyRecipes.filter(r => recipeCourse(r.id) === course);
  const lane = all.filter((_, index) => index % 2 === ((ordinal % 2) + 2) % 2);
  const season = seasonOf(day);
  const seasonal = lane.filter(r => !r.season || r.season === season);
  const pool = seasonal.length ? seasonal : lane;
  const context = dailyFoodContext(dates,day);
  const hash = (text:string)=>text.split('').reduce((h,c)=>Math.imul(h ^ c.charCodeAt(0),16777619)>>>0,2166136261);
  const seed = hash(JSON.stringify(context));
  const cuisines = ['japanese','western','asian'] as const;
  const desired = cuisines[(Math.floor(ordinal / 2) + hash(dates.join('|'))) % 3];
  const varied = course==='main' ? pool.filter(r=>recipeCuisine(r)===desired) : pool;
  const candidates = varied.length ? varied : pool;
  const score = (r: Recipe) => Number(r.element === element) * 2 + Number(r.season === season) * 2 + Number(context.dailyBalance[r.element]===0) + dates.filter(b => r.rhythm && r.rhythm === rhythmOf(b, day)).length;
  const ordered = [...candidates].sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id));
  const index = (Math.floor(ordinal / 2) + seed + ELEMENTS.indexOf(element) * 5 + i * 7) % ordered.length;
  const recipe = ordered[(index + ordered.length) % ordered.length];
  return recipe ? [recipe] : [];
});
